NullUUID represents a UUID that may be null.
NullUUID implements the SQL driver.Scanner interface so
it can be used as a scan destination:

 var u uuid.NullUUID
 err := db.QueryRow("SELECT name FROM foo WHERE id=?", id).Scan(&u)
 ...
 if u.Valid {
    // use u.UUID
 } else {
    // NULL value
 }

